// Package catalog holds the pinned list of llama.cpp builds, uv binaries and models. The
// embedded catalog.json is generated by engine/tools/gencatalog; nothing is hand-typed.
package catalog

import (
	_ "embed"
	"encoding/json"
	"fmt"
	"log"
	neturl "net/url"
	"os"
	"path/filepath"
	"reflect"
	"regexp"
	"strings"
	"sync"

	"github.com/CharlesMod/easyEngine/core/fit"

	"github.com/CharlesMod/easyEngine/probe"
)

//go:embed catalog.json
var embedded []byte

type Asset struct {
	ID     string `json:"id"`
	OS     string `json:"os"`   // linux | windows | darwin
	Arch   string `json:"arch"` // amd64 | arm64
	Accel  string `json:"accel,omitempty"`
	URL    string `json:"url"`
	SHA256 string `json:"sha256"`
	Size   int64  `json:"size"`
	// UnpackedSize is the disk the unpacked archive takes, measured by gencatalog when it
	// generates the catalog: every file rounded up to a 4 KiB block plus 4 KiB per directory
	// (ext4 and NTFS allocate in 4 KiB clusters, so this is an upper bound there). 0 = unknown.
	UnpackedSize int64    `json:"unpacked_size,omitempty"`
	Extra        []string `json:"extra,omitempty"` // ids of further assets unpacked into the same dir (cudart)

	// Which build of llama.cpp a llama asset belongs to, filled from its rung by Backends, Asset
	// and LlamaAsset (never written to the file): the rung's full tag (b12651-easy1, not 12651),
	// whether it is a patched build, the rung's place (0 = the pin) and, for a build that is
	// not patched, why this machine gets it.
	Tag     string `json:"-"`
	Patched bool   `json:"-"`
	Rung    int    `json:"-"`
	RungWhy string `json:"-"`
}

// LlamaCpp is one rung of the llama.cpp ladder: one release's builds. The catalog names the
// rungs in order (Catalog.Llama): the patched pin first (a release of the fork, tag
// b<N>-easy<M>), then the stock upstream release, whose builds are offered only for a platform
// and accelerator the patched release has no build for (docs/ENGINE.md, "Which llama.cpp build").
type LlamaCpp struct {
	Tag     string  `json:"tag"`
	Repo    string  `json:"repo,omitempty"`    // owner/name of the GitHub repo the release is in
	Patched bool    `json:"patched,omitempty"` // a patched build (the fork's), not stock upstream
	Assets  []Asset `json:"assets"`
}

// PatchedTag reports whether a tag names a patched build of the fork (b12651-easy1).
func PatchedTag(tag string) bool { return strings.Contains(tag, "-easy") }

type Model struct {
	ID      string `json:"id"`
	Name    string `json:"name"`
	File    string `json:"file"`
	URL     string `json:"url"` // empty: import-only
	SHA256  string `json:"sha256"`
	Size    int64  `json:"size"`
	MoE     bool   `json:"moe"`
	Quality int    `json:"quality"`
	Chat    string `json:"chat,omitempty"`
	Notes   string `json:"notes,omitempty"`
	// Fallback marks a model that is only there so a small machine has something to run. A
	// front end should warn when it is in use; FallbackNote says why in a sentence.
	Fallback     bool   `json:"fallback,omitempty"`
	FallbackNote string `json:"fallback_note,omitempty"`
	// Footprint is what a real llama-server took for this file on a reference machine. The
	// planner uses it for a model that is not downloaded yet; once the file is on disk the GGUF
	// header gives the same numbers (docs/FOOTPRINTS.md). Generated, never typed: tools/fitcheck
	// fits it from the sweep CSV into tools/gencatalog/measured.json.
	Footprint *Footprint `json:"footprint,omitempty"`
	// Sampler holds the named sampler profiles (official, rp, structured, ...). official is the
	// vendor's own values and is also what llama-server starts with as its defaults. Generated
	// from tools/gencatalog's spec; see docs/SAMPLERS.md.
	Sampler map[string]SamplerProfile `json:"sampler,omitempty"`
	// SamplerSource says where the official values came from (URL and commit).
	SamplerSource string `json:"sampler_source,omitempty"`
	// SamplerMatch lists name fragments by which an external endpoint's model name is
	// recognised as this model (see ModelByName).
	SamplerMatch []string `json:"sampler_match,omitempty"`
}

// TPSPoint is a measured per-stream decode speed with NCpuMoe expert layers on the CPU. It is
// the sizing core's type, so a measured block feeds the core's speed curve as it is.
type TPSPoint = fit.TPSPoint

// MeasuredOn says where a footprint came from.
type MeasuredOn struct {
	GPU      string `json:"gpu"`
	VRAMMiB  int    `json:"vram_mib"`
	Backend  string `json:"backend"`
	LlamaCpp string `json:"llamacpp"`
	Date     string `json:"date"`
	Flags    string `json:"flags,omitempty"`
}

// Footprint is the measured memory and speed of one model. Process VRAM in MiB:
//
//	vram = fixed_mib + mib_per_1k_ctx[kv] * ctx_total/1024 + state_mib_per_slot[kv] * slots + scratch_mib
//	       - expert_mib_per_layer * n_cpu_moe + (n_cpu_moe > 0 ? moe_sched_mib : 0)
//
// "1k" is 1024 tokens. state_mib_per_slot is the per-slot cost: the sliding-window cache
// (it scales with the KV type) and any recurrent state.
type Footprint struct {
	FixedMiB             float64            `json:"fixed_mib"`
	MiBPer1kCtx          map[string]float64 `json:"mib_per_1k_ctx"`
	StateMiBPerSlot      map[string]float64 `json:"state_mib_per_slot"`
	ScratchMiB           float64            `json:"scratch_mib"`
	HostMiB              float64            `json:"host_mib,omitempty"` // weights that stay in RAM with -ngl 999
	ExpertMiBPerLayer    float64            `json:"expert_mib_per_layer,omitempty"`
	ExpertRAMMiBPerLayer float64            `json:"expert_ram_mib_per_layer,omitempty"`
	ExpertLayers         int                `json:"expert_layers,omitempty"`
	MoESchedMiB          float64            `json:"moe_sched_mib,omitempty"`
	// DecodeTPS and PromptTPS are per stream at the reference shape (q4_0, 65536 ctx per slot,
	// every layer on the card), keyed by the number of slots decoding at once ("1","2","3").
	DecodeTPS map[string]float64 `json:"decode_tps,omitempty"`
	PromptTPS map[string]float64 `json:"prompt_tps,omitempty"`
	// TPSByNCpuMoe is decode speed against --n-cpu-moe at 3 slots x 65536, q4_0.
	TPSByNCpuMoe []TPSPoint `json:"tps_by_n_cpu_moe,omitempty"`
	MeasuredOn   MeasuredOn `json:"measured_on"`
}

type Catalog struct {
	Version int `json:"version"`
	// Llama is the ordered ladder of llama.cpp releases (version 10 on): the patched pin first,
	// stock upstream after it. Rungs() reads it.
	Llama []LlamaCpp `json:"llama,omitempty"`
	// LlamaCpp is the one release a catalog before version 10 names; still read (Rungs treats
	// it as the only rung), never written by gencatalog any more.
	LlamaCpp LlamaCpp `json:"llamacpp,omitzero"`
	UV       []Asset  `json:"uv"`
	Models   []Model  `json:"models"`
	// AgentRuntime is the measured disk a fresh agent setup takes (managed Python, the uv
	// cache and the agent's venv or site dir), per OS. It is a default: a profile's agent
	// block may declare its own figure (run.AgentSpec.DiskBytes).
	AgentRuntime []RuntimeSize `json:"agent_runtime,omitempty"`
}

// RuntimeSize is one measured agent setup: the peak extra disk while it installs and what
// stays after. Measured by a real install (tools/gencatalog/runtime.json says how and when).
type RuntimeSize struct {
	OS           string `json:"os"`
	Arch         string `json:"arch"`
	Python       string `json:"python"`
	PeakBytes    int64  `json:"peak_bytes"`
	KeepBytes    int64  `json:"keep_bytes"`
	MeasuredOn   string `json:"measured_on"`   // date and machine
	MeasuredWith string `json:"measured_with"` // the wheel and uv version measured
}

// RuntimeFor returns the measured agent setup for an OS/arch, falling back to the same OS on
// another arch.
func (c *Catalog) RuntimeFor(goos, goarch string) (RuntimeSize, bool) {
	var alt *RuntimeSize
	for i, r := range c.AgentRuntime {
		if r.OS == goos && r.Arch == goarch {
			return r, true
		}
		if r.OS == goos && alt == nil {
			alt = &c.AgentRuntime[i]
		}
	}
	if alt != nil {
		return *alt, true
	}
	return RuntimeSize{}, false
}

// Parse decodes and validates a catalog document. Ids and file names become paths that are
// created and deleted under the data dir, and urls are fetched, so a catalog is refused unless
// every asset id, model id and model file is a plain name, every url is https (http only for a
// loopback host) and every download has a sha256 and a size.
func Parse(b []byte) (*Catalog, error) {
	var c Catalog
	if err := json.Unmarshal(b, &c); err != nil {
		return nil, fmt.Errorf("catalog: %w", err)
	}
	if c.Version <= 0 {
		return nil, fmt.Errorf("catalog: missing version")
	}
	if err := c.validate(); err != nil {
		return nil, fmt.Errorf("catalog: %w", err)
	}
	return &c, nil
}

var (
	plainName = regexp.MustCompile(`^[A-Za-z0-9_-][A-Za-z0-9._-]*$`)
	shaRE     = regexp.MustCompile(`^[0-9a-fA-F]{64}$`)
)

func checkName(kind, v string) error {
	if !plainName.MatchString(v) {
		return fmt.Errorf("%s %q is not a plain name (letters, digits, . _ - only; no leading dot, no path separator)", kind, v)
	}
	return nil
}

func checkDownload(kind, id, url, sha string, size int64) error {
	if url == "" {
		return nil
	}
	u, err := neturl.Parse(url)
	if err != nil || u.Host == "" {
		return fmt.Errorf("%s %q: bad url", kind, id)
	}
	switch u.Scheme {
	case "https":
	case "http":
		switch u.Hostname() {
		case "127.0.0.1", "localhost", "::1":
		default:
			return fmt.Errorf("%s %q: url must be https", kind, id)
		}
	default:
		return fmt.Errorf("%s %q: url must be https", kind, id)
	}
	if !shaRE.MatchString(sha) {
		return fmt.Errorf("%s %q has a url but no valid sha256", kind, id)
	}
	if size <= 0 {
		return fmt.Errorf("%s %q has a url but no positive size", kind, id)
	}
	return nil
}

// Rungs returns the llama.cpp ladder, pin first. An older catalog's one release is the only rung;
// its Patched is read from its tag.
func (c *Catalog) Rungs() []LlamaCpp {
	if len(c.Llama) > 0 {
		return c.Llama
	}
	if c.LlamaCpp.Tag == "" && len(c.LlamaCpp.Assets) == 0 {
		return nil
	}
	l := c.LlamaCpp
	l.Patched = l.Patched || PatchedTag(l.Tag)
	return []LlamaCpp{l}
}

func (c *Catalog) validate() error {
	if len(c.Llama) > 0 && (c.LlamaCpp.Tag != "" || len(c.LlamaCpp.Assets) > 0) {
		return fmt.Errorf("both llama (the ladder) and llamacpp (one release) are set")
	}
	assets := append([]Asset{}, c.UV...)
	tags := map[string]bool{}
	for _, r := range c.Rungs() {
		if err := checkName("llama.cpp tag", r.Tag); err != nil {
			return err
		}
		if tags[r.Tag] {
			return fmt.Errorf("llama.cpp tag %q is named twice", r.Tag)
		}
		tags[r.Tag] = true
		ids := map[string]bool{}
		for _, a := range r.Assets {
			if ids[a.ID] {
				return fmt.Errorf("llama.cpp %s names asset %q twice", r.Tag, a.ID)
			}
			ids[a.ID] = true
		}
		for _, a := range r.Assets {
			for _, x := range a.Extra {
				if !ids[x] {
					return fmt.Errorf("llama.cpp %s: asset %q needs %q, which that release does not name", r.Tag, a.ID, x)
				}
			}
		}
		assets = append(assets, r.Assets...)
	}
	for _, a := range assets {
		if err := checkName("asset id", a.ID); err != nil {
			return err
		}
		if err := checkDownload("asset", a.ID, a.URL, a.SHA256, a.Size); err != nil {
			return err
		}
	}
	for _, m := range c.Models {
		if err := checkModel(m); err != nil {
			return err
		}
	}
	return nil
}

func checkModel(m Model) error {
	if err := checkName("model id", m.ID); err != nil {
		return err
	}
	if err := checkName("model file", m.File); err != nil {
		return err
	}
	return checkDownload("model", m.ID, m.URL, m.SHA256, m.Size)
}

// MaxOverlayModels is how many models one overlay may add.
const MaxOverlayModels = 16

// WithModels is a copy of c with extra models added after its own (a client's local overlay):
// each is checked by the rules of a catalog entry (a plain id and file name, an https or loopback
// URL with its sha256 and size, or none for an import-only entry). An id that c already has is
// refused unless the entry is the same one (an overlay brought again adds nothing): an id means
// one thing to every client, and a built-in is never replaced. Two models of the overlay may not
// share an id or a file, nor take a file c's models use. c itself is not changed.
func (c *Catalog) WithModels(extra []Model) (*Catalog, error) {
	if len(extra) > MaxOverlayModels {
		return nil, fmt.Errorf("an overlay adds at most %d models, not %d", MaxOverlayModels, len(extra))
	}
	ids, files := map[string]Model{}, map[string]string{}
	for _, m := range c.Models {
		ids[m.ID] = m
		files[m.File] = m.ID
	}
	out := *c
	out.Models = append([]Model{}, c.Models...)
	for _, m := range extra {
		if err := checkModel(m); err != nil {
			return nil, err
		}
		if have, ok := ids[m.ID]; ok {
			if reflect.DeepEqual(have, m) {
				continue
			}
			return nil, fmt.Errorf("model id %q is already in the catalog: an overlay adds models, never replaces one", m.ID)
		}
		if id, ok := files[m.File]; ok {
			return nil, fmt.Errorf("model file %q is already %q's", m.File, id)
		}
		ids[m.ID], files[m.File] = m, m.ID
		out.Models = append(out.Models, m)
	}
	return &out, nil
}

var reported sync.Map // override-problem notes already logged

// Load returns the embedded catalog, or <dataDir>/catalog.json when that file is valid and its
// version is higher. An override that fails validation is ignored and logged once; LoadNote
// returns the reason so a caller can show it.
func Load(dataDir string) (*Catalog, error) {
	c, note, err := LoadNote(dataDir)
	if note != "" {
		if _, seen := reported.LoadOrStore(note, true); !seen {
			log.Printf("catalog: %s", note)
		}
	}
	return c, err
}

// LoadNote is Load that also returns a note when an override file was ignored because it did not parse or validate.
func LoadNote(dataDir string) (*Catalog, string, error) {
	c, err := Parse(embedded)
	if err != nil {
		return nil, "", err
	}
	if dataDir != "" {
		path := filepath.Join(dataDir, "catalog.json")
		if b, err := os.ReadFile(path); err == nil {
			o, err := Parse(b)
			if err != nil {
				return c, fmt.Sprintf("%s was ignored: %v", path, err), nil
			}
			if o.Version > c.Version {
				return o, "", nil
			}
		}
	}
	return c, "", nil
}

func (c *Catalog) Model(id string) (Model, bool) {
	for _, m := range c.Models {
		if m.ID == id {
			return m, true
		}
	}
	return Model{}, false
}

// Asset finds a llama.cpp or uv asset by id. A llama.cpp id is resolved as Backends resolves
// it: from the first rung that has a build of that platform and accelerator.
func (c *Catalog) Asset(id string) (Asset, bool) {
	for _, a := range c.llamaAll() {
		if a.ID == id && c.offered(a) {
			a.RungWhy = c.rungWhy(a)
			return a, true
		}
	}
	for _, a := range c.UV {
		if a.ID == id {
			return a, true
		}
	}
	return Asset{}, false
}

// UVFor returns the uv binary for an OS and architecture.
func (c *Catalog) UVFor(goos, goarch string) (Asset, bool) {
	for _, a := range c.UV {
		if a.OS == goos && a.Arch == goarch {
			return a, true
		}
	}
	return Asset{}, false
}

var blackwell = regexp.MustCompile(`(?i)RTX\s*(PRO\s*)?(50\d\d|[4-9]\d\d\d\s*Blackwell)|\bB[1-9]\d{2}\b|\bGB\d{3}`)

// preTuring names NVIDIA cards older than Turing (Maxwell, Pascal, Volta): CUDA 13 no longer
// builds for them, so a CUDA 13 build is never offered to a machine whose cards are all such.
//
// The names, from NVIDIA's own lists: Volta (TITAN V, Quadro GV100, Tesla V100, V100S), Pascal
// (GeForce GTX 10xx, GT 1030, MX 1xx/2xx/3xx, TITAN X/Xp, Quadro P and GP100, Tesla P4/P6/P40/P100),
// Maxwell (GTX 9xx and 750, Quadro M, Tesla M, the Maxwell TITAN X) and Kepler (GTX 6xx/7xx,
// Quadro K, Tesla K). GTX 16xx, the RTX cards, Quadro RTX, TITAN RTX and Tesla T4 are Turing or
// later and are not matched.
var preTuring = regexp.MustCompile(`(?i)\bGTX\s*(6\d\d|7\d\d|9\d\d|10\d\d)\b|\bGT\s*10[34]0\b|\bMX\s*[1-3]\d0\b|\bTITAN\s*(X|Xp|V|Black|Z)\b|\bQuadro\s*(GV100|GP100|[KMP]\d)|\bTesla\s*([KMP]\d|V100)|\bV100S?\b|\bP100\b|\bP(4|6|40)\b`)

// Driver floors (NVIDIA's CUDA compatibility table): a CUDA 13 build needs driver 580 or later,
// a CUDA 12 build 525 or later (minor-version compatibility). An unknown driver (0) passes.
const cuda13Driver, cuda12Driver = 580, 525

// driverMajor is the major number of an NVIDIA driver version ("580.95.05", "581.57"), 0 when
// unknown.
func driverMajor(v string) int {
	n := 0
	for _, r := range v {
		if r < '0' || r > '9' {
			break
		}
		n = n*10 + int(r-'0')
	}
	return n
}

// Backends returns the llama.cpp builds to try on hw, best first: NVIDIA gets cuda, AMD and
// Intel get vulkan, Apple Silicon gets metal, and everything falls back through vulkan (when a
// GPU exists) to cpu. Each build comes from the first rung of the ladder that has a build for
// that platform and accelerator (the patched pin; stock only where the pin has none), and the
// list never holds two rungs' builds of one platform and accelerator.
//
// Among CUDA builds: the CUDA 13 build (id prefix "cuda13") comes first for Blackwell and the
// CUDA 12 one for every other card; a CUDA 13 build is left out when every NVIDIA card is
// older than Turing or the driver is older than 580, a CUDA 12 build when the driver is older
// than 525. On a mixed machine an NVIDIA card gets CUDA whatever else sits beside it (the
// device pin, plan.PinDevice, holds the server to the planned card).
func (c *Catalog) Backends(hw probe.Hardware) []Asset {
	var cand []Asset
	for _, a := range c.llamaAll() {
		if a.OS == hw.OS && a.Arch == hw.Arch && a.Accel != "cudart" && c.offered(a) {
			a.RungWhy = c.rungWhy(a)
			cand = append(cand, a)
		}
	}
	pick := func(accel string) []Asset {
		var out []Asset
		for _, a := range cand {
			if a.Accel == accel {
				out = append(out, a)
			}
		}
		return out
	}
	var nv, amdIntel, apple, anyGPU bool
	blackwellGPU, modernNV := false, false
	driver := 0
	for _, g := range hw.GPUs {
		anyGPU = true
		switch g.Vendor {
		case "nvidia":
			nv = true
			if blackwell.MatchString(g.Name) {
				blackwellGPU = true
			}
			if !preTuring.MatchString(g.Name) {
				modernNV = true
			}
			if d := driverMajor(g.Driver); d > 0 && (driver == 0 || d < driver) {
				driver = d
			}
		case "amd", "intel", "other":
			amdIntel = true
		case "apple":
			apple = true
		}
	}
	var order []Asset
	if nv {
		cu := pick("cuda")
		var newer, older []Asset
		for _, a := range cu {
			if strings.HasPrefix(a.ID, "cuda13") {
				if modernNV && (driver == 0 || driver >= cuda13Driver) {
					newer = append(newer, a)
				}
			} else if driver == 0 || driver >= cuda12Driver {
				older = append(older, a)
			}
		}
		if blackwellGPU {
			order = append(order, newer...)
			order = append(order, older...)
		} else {
			order = append(order, older...)
			if len(older) == 0 {
				order = append(order, newer...)
			}
		}
	}
	if apple {
		order = append(order, pick("metal")...)
	}
	if nv || amdIntel || (anyGPU && !apple) {
		order = append(order, pick("vulkan")...)
	}
	order = append(order, pick("cpu")...)
	return order
}

// llamaAll is every llama.cpp asset of every rung, in ladder order, each marked with its rung.
func (c *Catalog) llamaAll() []Asset {
	var out []Asset
	for i, r := range c.Rungs() {
		for _, a := range r.Assets {
			a.Tag, a.Patched, a.Rung = r.Tag, r.Patched, i
			out = append(out, a)
		}
	}
	return out
}

// offered reports whether a's rung is the one a machine of a's platform and accelerator gets:
// the first rung with a build for that platform and accelerator. A later (stock) rung never
// stands in for an earlier one that has such a build, whatever happens to that build at runtime.
func (c *Catalog) offered(a Asset) bool {
	for _, b := range c.llamaAll() {
		if b.Rung >= a.Rung {
			break
		}
		if b.OS == a.OS && b.Arch == a.Arch && b.Accel == a.Accel {
			return false
		}
	}
	return true
}

func (c *Catalog) rungWhy(a Asset) string {
	switch {
	case a.Patched:
		return ""
	case a.Rung == 0:
		return "the catalog names no patched build"
	default:
		return fmt.Sprintf("no patched build for %s/%s (%s)", a.OS, a.Arch, a.Accel)
	}
}

// LlamaAsset finds asset id in the rung tagged tag: a build's extras (cudart) come from the
// build's own release, and an installed build is looked up by the tag it was installed from.
func (c *Catalog) LlamaAsset(tag, id string) (Asset, bool) {
	for _, a := range c.llamaAll() {
		if a.Tag == tag && a.ID == id {
			a.RungWhy = c.rungWhy(a)
			return a, true
		}
	}
	return Asset{}, false
}
